var e={"app.name":`Context Commander`,"app.skipToContent":`Przejdź do treści`,"nav.dashboard":`Pulpit`,"nav.projects":`Projekty`,"nav.organizations":`Organizacje`,"nav.registry":`Rejestr skilli`,"nav.administration":`Administracja`,"nav.workspace":`Obszar pracy`,"nav.installation":`Instalacja`,"nav.preferences":`Ustawienia`,"nav.signOut":`Wyloguj się`,"find.open":`Szukaj`,"find.placeholder":`Przejdź do projektu, skilla, ekranu…`,"find.project":`Projekt`,"find.skill":`Skill`,"find.screen":`Ekran`,"find.nothing":`Nic nie pasuje`,"find.hint":`{shortcut} otwiera to okno. ↑↓ przesuwa, Enter przechodzi, Esc zamyka.`,"theme.dark":`Ciemny`,"theme.light":`Jasny`,"theme.label":`Motyw`,"auth.title":`Zaloguj się`,"auth.withPassword":`E-mail i hasło`,"auth.withToken":`Token dostępu`,"auth.email":`E-mail`,"auth.emailOrUsername":`E-mail lub nazwa użytkownika`,"auth.directoryUnavailable":`Nie udało się połączyć z katalogiem. To nie wina Twojego hasła — spróbuj za chwilę albo powiadom osobę administrującą tą instalacją.`,"auth.directoryNoEmail":`Twój wpis w katalogu nie ma adresu e-mail, więc nie można utworzyć dla niego konta. Musi go dodać osoba z uprawnieniami administracyjnymi.`,"auth.password":`Hasło`,"auth.failed":`Nieprawidłowy e-mail lub hasło.`,"auth.tokenLabel":`Token dostępu`,"auth.tokenLead":`Osobisty token dostępu utworzony poleceniem {command}. Jest wymieniany na sesję i nie zapisuje się w tej przeglądarce.`,"auth.tokenFailed":`Ten token nie został przyjęty.`,"auth.rateLimited":`Zbyt wiele prób. Odczekaj chwilę i spróbuj ponownie.`,"auth.withProvider":`Zaloguj się przez {provider}`,"auth.oidcCancelled":`Logowanie zostało anulowane u dostawcy logowania.`,"auth.oidcExpired":`Ta próba logowania wygasła albo została rozpoczęta w innym oknie. Zacznij od nowa.`,"auth.oidcUnavailable":`Nie udało się połączyć z dostawcą logowania. To nie wina Twojego konta — spróbuj za chwilę albo powiadom osobę administrującą tą instalacją.`,"auth.oidcNoEmail":`Twoje konto u dostawcy logowania nie ma adresu e-mail, więc nie można utworzyć dla niego konta. Musi go dodać osoba administrująca dostawcą.`,"auth.oidcEmailUnverified":`Twój adres e-mail u dostawcy logowania nie jest zweryfikowany, więc nie można nim się tu zalogować. Zweryfikuj go tam i spróbuj ponownie.`,"auth.oidcFailed":`Logowanie przez dostawcę nie powiodło się. Zacznij od nowa.`,"auth.oidcNoAccount":`Logowanie u dostawcy się udało, ale nie masz tu konta, a ta instalacja nie tworzy ich automatycznie. Poproś osobę administrującą o utworzenie konta na Twój adres e-mail.`,"auth.oidcDomainNotAllowed":`Twój adres e-mail nie należy do domeny, którą ta instalacja akceptuje przy logowaniu przez tego dostawcę.`,"auth.indistinct":`Błędne hasło, adres bez konta i konto bez hasła czyta się tu identycznie. Powiedzenie, który to przypadek, zdradziłoby zgadującemu, że połowa jego domysłu była trafna.`,"setup.title":`Utwórz pierwsze konto administracyjne`,"setup.lead":`Ta instalacja nie ma jeszcze użytkowników. Serwer przy starcie zapisał w swoim logu jednorazowy kod instalacyjny — wklej go tutaj.`,"setup.code":`Kod instalacyjny`,"setup.email":`E-mail`,"setup.name":`Nazwa wyświetlana`,"setup.password":`Hasło`,"setup.passwordHint":`Co najmniej {min} znaków. Długość to jedyna reguła.`,"setup.submit":`Utwórz konto administracyjne`,"setup.codeFailed":`Ten kod instalacyjny jest nieprawidłowy. Aktualny znajduje się w logu serwera; restart wypisuje nowy.`,"setup.alreadyDone":`Ta instalacja ma już użytkowników. Zaloguj się zamiast tego.`,"setup.whereIsTheCode":`Kod istnieje wyłącznie w pamięci działającego serwera i tylko dopóki nie ma użytkowników — nigdy nie trafia do kopii zapasowej i nie da się go odczytać z bazy danych.`,"account.password":`Hasło`,"account.passwordLead":`Służy do logowania w tym interfejsie. Agenci i wiersz poleceń używają tokenów dostępu, zarządzanych osobno.`,"account.currentPassword":`Aktualne hasło`,"account.newPassword":`Nowe hasło`,"account.confirmPassword":`Powtórz nowe hasło`,"account.setPassword":`Ustaw hasło`,"account.changePassword":`Zmień hasło`,"account.passwordSet":`Hasło zmienione.`,"account.passwordMismatch":`Oba nowe hasła nie są takie same.`,"account.currentWrong":`Aktualne hasło jest nieprawidłowe.`,"account.noPasswordYet":`To konto nie ma jeszcze hasła. Jesteś zalogowany tokenem dostępu, a to wystarczający dowód, by je ustawić.`,"account.sessions":`Sesje`,"account.sessionsLead":`Gdzie to konto jest zalogowane. Zakończenie sesji natychmiast unieważnia jej ciasteczko, na którejkolwiek maszynie się znajduje.`,"account.sessionCurrent":`Ta przeglądarka`,"account.sessionStarted":`Rozpoczęta`,"account.sessionLastUsed":`Ostatnio użyta`,"account.sessionExpires":`Wygasa`,"account.endSession":`Zakończ sesję`,"account.noSessions":`Brak aktywnych sesji.`,"auth.submit":`Zaloguj się`,"auth.signedInAs":`Zalogowano jako {name}`,"common.loading":`Wczytywanie…`,"common.retry":`Spróbuj ponownie`,"common.cancel":`Anuluj`,"common.close":`Zamknij`,"common.loadMore":`Wczytaj więcej`,"common.showingMore":`Pokazano {count} · jest więcej`,"common.showingAll":`Pokazano {count} · to wszystko`,"common.endOfList":`Koniec listy`,"common.none":`Brak`,"common.never":`Nigdy`,"common.unknown":`Nieznane`,"common.you":`Ty`,"common.copy":`Kopiuj`,"common.copied":`Skopiowano`,"common.copyFailed":`Nie udało się skopiować — zaznacz wartość i skopiuj ją samodzielnie`,"error.forbidden.title":`Nie masz do tego dostępu`,"error.forbidden.body":`Twoja rola w tym projekcie nie obejmuje uprawnienia, którego ten ekran potrzebuje. Zapytaj właścicielkę lub administratora, czy powinna je obejmować.`,"error.notFound.title":`Nie znaleziono`,"error.notFound.body":`To nie istnieje albo nie jest dla Ciebie widoczne.`,"error.conflict.generic":`Tego nie udało się wykonać`,"error.unavailable.title":`Serwer nie odpowiada`,"error.unavailable.body":`Nic nie zostało zmienione. Spróbuj za chwilę.`,"error.rateLimited.title":`Zbyt wiele żądań`,"error.rateLimited.body":`To poświadczenie wysyła żądania zbyt szybko. Odczekaj chwilę i spróbuj ponownie.`,"error.generic.title":`Coś poszło nie tak`,"error.crashed.title":`Ten ekran przestał działać`,"error.crashed.body":`Coś w interfejsie zawiodło podczas rysowania tej strony. Nic z tego, co oglądałaś lub oglądałeś, nie zostało zmienione na serwerze. Przeładowanie zwykle to naprawia; jeśli nie, szczegół poniżej jest tym, co warto zgłosić.`,"error.crashed.reload":`Przeładuj`,"error.notFoundPage.title":`Nie ma takiej strony`,"error.notFoundPage.body":`Ten adres nie odpowiada niczemu w tym interfejsie.`,"error.backToDashboard":`Przejdź do pulpitu`,"empty.noResults":`Nic nie pasuje`,"empty.noResultsBody":`Spróbuj innego wyszukiwania albo zdejmij filtry.`,"dashboard.title":`Pulpit`,"dashboard.lead":`Co się zmieniło, gdzie pracowałaś lub pracowałeś i czy coś na Ciebie czeka.`,"dashboard.waiting":`Czeka na Ciebie`,"dashboard.yourProjects":`Twoje projekty`,"dashboard.noneWaiting":`Nic na Ciebie nie czeka`,"dashboard.noneWaitingBody":`Żadnych otwartych przekazań, żadnych odmów wartych spojrzenia.`,"projects.title":`Projekty`,"projects.lead":`Wszystkie projekty, w których możesz działać. Ścieżka to sposób, w jaki mówią o nim ludzie; UUID to to, co ma na myśli system.`,"projects.filter":`Filtruj projekty…`,"projects.column.project":`Projekt`,"projects.column.role":`Twoja rola`,"projects.count":`{count, plural, one {# projekt} few {# projekty} many {# projektów} other {# projektu}}`,"projects.empty":`Nie należysz do żadnego projektu`,"projects.emptyBody":`Projekt pojawia się tutaj, gdy ktoś Cię do niego doda.`,"project.identity":`Tożsamość`,"project.path":`Ścieżka`,"project.uuid":`UUID`,"handoff.current":`Bieżące przekazanie`,"handoff.summary":`Podsumowanie`,"handoff.completed":`Wykonana praca`,"handoff.next":`Następne kroki`,"handoff.references":`Odniesienia`,"handoff.claim":`Przejmij`,"handoff.close":`Zamknij przekazanie`,"handoff.create":`Utwórz przekazanie`,"handoff.status.open":`Otwarte`,"handoff.status.claimed":`Przejęte`,"handoff.status.closed":`Zamknięte`,"handoff.claimedBy":`Przekazanie przejęte przez {name}`,"handoff.claimedByYou":`Przekazanie przejęte przez Ciebie`,"handoff.none":`Żadne przekazanie nie jest otwarte`,"handoff.noneBody":`Nic tutaj nie czeka na przejęcie.`,"handoff.alreadyClaimed":`Inny klient przejął to pierwszy`,"handoff.alreadyClaimedBody":`To odpowiedź koordynacji, nie błąd w Twoim żądaniu. Przeczytaj przekazanie ponownie i zdecyduj, czy ta praca nadal należy do Ciebie.`,"members.title":`Członkowie`,"members.lead":`Kto może działać w tym projekcie i w jakiej roli. Poświadczenie klienta nie jest członkiem — jest nim principal, który za nim stoi.`,"members.column.principal":`Principal`,"members.column.role":`Rola`,"members.column.added":`Dodano`,"members.add":`Dodaj principala`,"members.count":`{count, plural, one {# członek} few {# członkowie} many {# członków} other {# członka}}`,"members.addHelp":`Rola w projekcie należy do principala — osoby albo agenta. Oba są tu do wyboru, jeśli administrujesz tą instalacją; w przeciwnym razie pole przyjmuje identyfikator principala, który nie jest tym samym co identyfikator konta.`,"members.principalPlaceholder":`UUID principala`,"picker.choose":`Wybierz kogoś…`,"picker.userId":`Identyfikator konta`,"picker.agent":`agent`,"picker.noDirectory":`Tylko osoba administrująca instalacją może wypisać jej użytkowników, więc to pole prosi o identyfikator, zamiast proponować wybór. Poproś o niego administratora albo skopiuj go z ekranu konta tej osoby.`,"members.noRemoval":`Usuwanie członka i zmiana roli nie są zrobione: API nie ma zapisu dla żadnej z tych operacji, więc ten ekran ich nie proponuje.`,"skills.title":`Skille`,"skills.lead":`Zbiór obowiązujący: powiązania instalacji, organizacji i projektu złożone razem, przy czym dla każdego skilla wygrywa najwęższe. Każde nadpisanie jest widoczne.`,"skills.column.skill":`Skill`,"skills.column.livesAt":`Mieszka w`,"skills.column.version":`Rozstrzygnięto na`,"skills.column.trust":`Zaufanie`,"skills.column.state":`Stan`,"skills.browse":`Przeglądaj rejestr`,"skills.install":`Zainstaluj skill`,"skills.empty":`Żaden skill tu nie obowiązuje`,"skills.emptyBody":`Zainstaluj jakiś z rejestru albo opublikuj własny z tego projektu.`,"registry.title":`Rejestr skilli`,"registry.lead":`Wszystko, co możesz zobaczyć: skille w Twoich projektach, w Twoich organizacjach i na półce instalacji. Agenci przeszukują ten sam katalog.`,"registry.search":`Szukaj skilla po nazwie…`,"registry.column.latest":`Najnowsza`,"registry.column.author":`Autor`,"registry.publish":`Nowy skill`,"registry.publishLead":`Skill to tekst instrukcji wręczany agentowi. Publikacja tworzy niezmienną wersję — poprawienie jej później oznacza opublikowanie kolejnej, a obie zostają.`,"registry.publishName":`Nazwa`,"registry.publishAuthor":`Autor`,"registry.publishOrigin":`Pochodzenie`,"registry.publishScope":`Opublikuj do`,"registry.publishContent":`Instrukcje`,"registry.published":`Opublikowano wersję {version}`,"registry.publishScopeHelp":`Gdzie mieszka, czyli kto go widzi w katalogu — a nie gdzie obowiązuje. Projekt może zainstalować skill mieszkający wszędzie, gdzie sięga jego widok.`,"registry.results":`{count, plural, one {# wynik} few {# wyniki} many {# wyników} other {# wyniku}} dla „{query}”`,"orgs.title":`Organizacje`,"orgs.lead":`Poziom powyżej Twoich projektów. W organizacji skill albo gate narzuca się raz, zamiast projekt po projekcie.`,"orgs.column.name":`Organizacja`,"orgs.column.role":`Twoja rola`,"orgs.empty":`Nie należysz do żadnej organizacji`,"orgs.emptyBody":`Członkostwo w organizacji przypisane jest do konta osoby, więc principal usługowy nigdy go nie ma — dla niego to właściwa odpowiedź, nie odmowa.`,"orgs.members":`Członkowie`,"orgs.membersLead":`Członkostwo dotyczy kont osób, nie principali: rola w organizacji mówi o człowieku, natomiast principal usługowy działa wewnątrz projektu.`,"orgs.audit":`Aktywność`,"orgs.column.user":`Konto`,"orgs.select":`Wybierz organizację`,"orgs.selectBody":`Wybierz jedną po lewej, aby zobaczyć jej członków i aktywność.`,"scope.installation":`Instalacja`,"scope.organization":`Organizacja`,"scope.project":`Projekt`,"trust.signed":`Podpisany`,"trust.unverified":`Niesprawdzony`,"role.OWNER":`Własność`,"role.ADMIN":`Administracja`,"role.CONTRIBUTOR":`Współpraca`,"role.READER":`Odczyt`,"activity.title":`Aktywność`,"activity.lead":`Zdarzenia i audyt na jednej osi czasu. Odpowiadają na to samo pytanie — co się tu stało — a rozdzielenie ich każe czytającemu zszywać je z powrotem.`,"activity.column.time":`Czas`,"activity.column.action":`Działanie`,"activity.column.resource":`Zasób`,"activity.column.principal":`Principal`,"activity.column.result":`Wynik`,"activity.result.allow":`Dozwolone`,"activity.result.deny":`Odmówione`,"activity.result.error":`Błąd`,"admin.title":`Administracja`,"admin.lead":`Sama instalacja: kto ją administruje, komu czego odmówiono i tożsamości, na których wisi wszystko pozostałe.`,"admin.tab.overview":`Przegląd`,"admin.tab.people":`Osoby`,"admin.tab.agents":`Agenci`,"admin.column.registeredBy":`Zarejestrował`,"admin.unattributed":`nie zapisano`,"admin.registeredByHelp":`Kto utworzył agenta. Jest to zapis jego pochodzenia i nie nadaje mu niczego — agent dociera do projektu wyłącznie przez własne członkostwo w nim.`,"admin.tab.usage":`Wykorzystanie`,"admin.usage":`Wykorzystanie`,"admin.usageLead":`Jak mocno ta instalacja jest naprawdę używana i ile w sobie trzyma. Tylko liczby — kto administruje instalacją, ten ją administruje, a nie czyta jej treści, więc nic tutaj nie nazywa projektu, ścieżki ani osoby.`,"admin.usage.content":`Co zawiera`,"admin.usage.coordination":`Koordynacja`,"admin.usage.activity":`Aktywność`,"admin.usage.credentials":`Poświadczenia`,"admin.usage.inOrganizations":`projektów, w {count, plural, one {# organizacji} few {# organizacjach} many {# organizacjach} other {# organizacji}}`,"admin.usage.andAgents":`osób, i {count, plural, one {# agent} few {# agenci} many {# agentów} other {# agenta}}`,"admin.usage.acrossArtifacts":`w {count, plural, one {# artefakcie} few {# artefaktach} many {# artefaktach} other {# artefaktu}}`,"admin.usage.ofIssued":`użytych poświadczeń, z {count, plural, one {# wydanego} few {# wydanych} many {# wydanych} other {# wydanego}}`,"admin.usage.artifacts":`Artefakty`,"admin.usage.versions":`Wersje`,"admin.usage.stored":`Zapisane`,"admin.usage.storedHelp":`Rozmiar wszystkich kiedykolwiek zapisanych wersji artefaktów. Nie zużycie dysku — baza danych nie widzi magazynu obiektów, a liczba podpisana „dysk” wzięta z SQL byłaby domysłem.`,"admin.usage.secrets":`Sekrety`,"admin.usage.conversations":`Rozmowy`,"admin.usage.historyObjects":`Zapisane obiekty`,"admin.usage.handoffsOpen":`Otwarte`,"admin.usage.handoffsClaimed":`Przejęte`,"admin.usage.handoffsClosed":`Zamknięte`,"admin.usage.handoffs":`Przekazania`,"admin.usage.skills":`Skille`,"admin.usage.skillVersions":`Wersje skilli`,"admin.usage.skillBindings":`Powiązania skilli`,"admin.usage.gateBindings":`Powiązania gate’ów`,"admin.usage.events":`Zdarzenia`,"admin.usage.auditRecords":`Wpisy audytu`,"admin.usage.securityEvents":`Zdarzenia bezpieczeństwa`,"admin.usage.newestActivity":`Ostatnia aktywność`,"admin.usage.oldestProject":`Pierwszy projekt`,"admin.usage.active":`Aktywne`,"admin.usage.revoked":`Odwołane`,"admin.usage.expired":`Wygasłe`,"admin.usage.usedRecentlyHelp":`Jedyna liczba, która odpowiada na „czy to jest używane”, a nie na „co tu leży”. Poświadczenie, które od tygodnia nie wysłało żadnego żądania, jest albo skończone, albo zapomniane.`,"admin.usage.quiet":`Jeszcze nic się nie stało`,"admin.usage.quietBody":`Żadnych zapisanych zdarzeń. Instalacja, która ma projekty, ale nie ma zdarzeń, to instalacja, do której nic nie zapisało.`,"admin.usage.weekly":`Ostatnie {count, plural, one {# tydzień} few {# tygodnie} many {# tygodni} other {# tygodnia}}`,"admin.usage.week":`Tydzień`,"admin.usage.people":`Osoby`,"admin.usage.agents":`Agenci`,"admin.usage.handedOff":`Przekazane`,"admin.usage.claimed":`Przejęte`,"admin.usage.byOtherClient":`Przejęte przez inny klient`,"admin.usage.medianToClaim":`Mediana do przejęcia`,"admin.usage.weeklyHelp":`Tygodnie zaczynają się w poniedziałek, w UTC. Osoby i agenci liczą się raz w tygodniu, jeśli wysłali jakiekolwiek uwierzytelnione żądanie; ten ekran może ich policzyć, ale nigdy nazwać.`,"admin.usage.loop":`Cykl przekazania`,"admin.usage.loopHelp":`Mierzone na podstawie tego, co zapisuje serwer: kiedy przekazanie zostało utworzone, przejęte i zamknięte oraz przez którego klienta. Czy następny agent zrozumiał, co mu przekazano, tego serwer nie widzi.`,"admin.usage.ofClaimed":`z {count, plural, one {# przejętego} few {# przejętych} many {# przejętych} other {# przejętego}}`,"admin.usage.ofProjects":`z {count, plural, one {# projektu} few {# projektów} many {# projektów} other {# projektu}}`,"admin.usage.projectsWithTakeover":`Projekty z przejęciem`,"admin.usage.firstTakeover":`Od startu projektu do pierwszego przejęcia (mediana)`,"admin.usage.p90ToClaim":`Czas do przejęcia, 90. percentyl`,"admin.usage.claimToClose":`Od przejęcia do zamknięcia (mediana)`,"admin.usage.staleOpen":`Otwarte dłużej niż 7 dni`,"admin.usage.notYet":`Jeszcze niezmierzone`,"admin.tab.security":`Dziennik bezpieczeństwa`,"admin.admins":`Administracja instalacji`,"admin.adminsLead":`Kto administruje instalacją, może czytać we wszystkich projektach. Nadawanie i odbieranie tego prawa nie odbywa się tutaj, i to celowo — to operacja wiersza poleceń.`,"admin.column.user":`Konto`,"admin.column.role":`Rola`,"admin.column.granted":`Nadano`,"admin.createUser":`Utwórz konto`,"admin.initialPassword":`Hasło początkowe (opcjonalne)`,"admin.initialPasswordLead":`Podane pozwala tej osobie zalogować się od razu. Puste oznacza, że będzie potrzebować tokenu albo hasła ustawionego później. Co najmniej {min} znaków.`,"admin.setPassword":`Ustaw hasło`,"admin.setPasswordFor":`Ustaw hasło dla {name}`,"admin.passwordSetFor":`Hasło ustawione. {name} może się nim teraz zalogować.`,"admin.setPasswordLead":`To możliwość zalogowania się jako ta osoba — to samo co wydanie jej tokenu, co ten ekran już robi. Przekaż hasło innym kanałem; później nie jest nigdzie pokazywane.`,"admin.createUserLead":`Osoba, która może trzymać token i zostać dodana do projektów.`,"admin.email":`Adres e-mail`,"admin.displayName":`Nazwa wyświetlana`,"admin.createService":`Utwórz principala usługowego`,"admin.createServiceLead":`Tożsamość nie-ludzka — zadanie CI, agent uruchamiany harmonogramem. Działa w projektach i pojawia się w audycie jak każdy inny.`,"admin.name":`Nazwa`,"admin.description":`Opis`,"admin.users":`Osoby`,"admin.usersLead":`Wszyscy, kto ma tożsamość w tej instalacji. Ich role w projektach mieszkają przy projekcie, nie tutaj.`,"admin.servicePrincipals":`Agenci`,"admin.servicePrincipalsLead":`Tożsamości nie-ludzkie — zadanie CI, agent uruchamiany harmonogramem. Taka tożsamość działa w projektach i pojawia się w audycie dokładnie tak jak człowiek, i o to właśnie chodzi: to, co zrobił agent, przypisuje się agentowi, a nie temu, kto go skonfigurował.`,"admin.column.name":`Nazwa`,"admin.column.created":`Utworzono`,"admin.noUsers":`Na razie nikt poza Tobą`,"admin.noServicePrincipals":`Nie zarejestrowano żadnego agenta`,"admin.noServicePrincipalsBody":`Zarejestruj jednego, a potem wydaj mu token — to ten token pokazuje zadanie CI albo agent z harmonogramu, wywołując ten serwer.`,"admin.issueFor":`Wydaj token`,"admin.tokens":`Tokeny`,"admin.tokensLead":`Wszystkie poświadczenia wydane tej tożsamości. Odwołanie działa od następnego żądania i nie zmienia żadnego członkostwa.`,"admin.noTokens":`Nie wydano żadnego tokenu`,"admin.confirmRevokeFor":`Odwołać to poświadczenie? To, co go używa, natychmiast przestanie działać, a jeśli jest to działający agent — polegnie w połowie zadania.`,"admin.issueForLead":`Token dla tej tożsamości, nie dla Ciebie. Pokazuje się raz i nigdy więcej, a kto go trzyma, działa jako ta tożsamość.`,"admin.security":`Dziennik bezpieczeństwa`,"admin.securityLead":`Czego serwer odmówił: token, który się nie rozwiązał, odmówione uprawnienie, ograniczony wywołujący. Trzymane osobno od audytu projektu i to celowo — odmowa często dotyczy projektu, którego wywołujący nawet nie widzi, a wzorzec, który naprawdę warto wychwycić, jedno poświadczenie obmacujące kilka projektów, jest niewidoczny z wnętrza któregokolwiek z nich.`,"admin.securityNote":`Udane zalogowanie nie jest odmową i nie jest tu zapisywane. To, co poświadczenie zrobiło ostatnio, widnieje na samym tokenie jako czas ostatniego użycia.`,"admin.column.kind":`Rodzaj`,"admin.column.reason":`Powód`,"admin.column.capability":`Uprawnienie`,"admin.securityEmpty":`Nic nie zapisano`,"admin.securityEmptyBody":`Żadnych odmów, żadnych nieznanych poświadczeń, nie ma na co patrzeć. To dobry przypadek.`,"tokens.title":`Tokeny dostępu`,"tokens.lead":`Poświadczenia, których używasz z CLI, edytora albo klienta MCP. Każde jest tylko Twoje — nie ma tu żadnego sposobu, by wydać token komuś innemu.`,"tokens.column.type":`Klient`,"tokens.column.created":`Utworzono`,"tokens.column.lastUsed":`Ostatnie użycie`,"tokens.column.expires":`Wygasa`,"tokens.issue":`Wydaj token`,"tokens.clientType":`Rodzaj klienta`,"tokens.expiry":`Okres ważności`,"tokens.expiry.never":`Bez wygaśnięcia`,"tokens.expiry.30d":`30 dni`,"tokens.expiry.90d":`90 dni`,"tokens.expiry.1y":`1 rok`,"tokens.revoke":`Odwołaj`,"tokens.revoked":`Odwołany`,"tokens.expired":`Wygasły`,"tokens.active":`Aktywny`,"tokens.empty":`Na razie żadnych tokenów`,"tokens.emptyBody":`Wydaj jeden, aby podłączyć agenta do tej instalacji.`,"tokens.justIssued":`Skopiuj ten token teraz`,"tokens.justIssuedBody":`Przechowywany jest tylko jego skrót, więc to jedyny raz, kiedy można go pokazać. Zamknięcie tego panelu go nie odwołuje — ale oznacza, że nie da się go już nigdy odczytać.`,"tokens.confirmRevoke":`Odwołać to poświadczenie? Wszystko, co go jeszcze używa, natychmiast przestanie działać.`,"prefs.title":`Ustawienia`,"prefs.lead":`Jak ta instalacja się do Ciebie zwraca. Te ustawienia idą za Twoim kontem, nie za tą przeglądarką.`,"prefs.language":`Język interfejsu`,"prefs.languageHelp":`Wszystko, co pisze produkt. Treści napisane przez innych nigdy nie są tłumaczone.`,"prefs.dateFormat":`Format daty`,"prefs.timeFormat":`Format godziny`,"prefs.timeZone":`Strefa czasowa`,"prefs.showUTC":`Pokazuj też UTC`,"prefs.numberFormat":`Format liczb`,"prefs.storageUnits":`Jednostki pamięci`,"prefs.units.decimal":`GB · dziesiętnie, podstawa 1000`,"prefs.units.binary":`GiB · binarnie, podstawa 1024`,"prefs.notStored":`Ustawienia nie są jeszcze przechowywane na serwerze, więc na razie mieszkają w tej przeglądarce.`,"prefs.section.language":`Język`,"prefs.section.dates":`Data i godzina`,"prefs.section.numbers":`Liczby i jednostki`,"prefs.dateFormatHelp":`Jak zapisuje się datę. 03-09-2026 oznacza dwa różne dni, zależnie od tego, kto to czyta.`,"prefs.timeFormatHelp":`Konwencja zegara.`,"prefs.timeZoneHelp":`Znaczniki czasu przechowywane są w UTC i pokazywane w tej strefie.`,"prefs.showUTCHelp":`Dla ekranów audytu i bezpieczeństwa, gdzie liczy się wspólny punkt odniesienia.`,"prefs.storageUnitsHelp":`Jak zapisuje się rozmiary w bajtach. Zapisana wartość nigdy się nie zmienia — zmienia się tylko jej odczyt.`,"prefs.date.locale":`Zgodnie z językiem`,"prefs.date.ymd":`RRRR-MM-DD`,"prefs.date.dmy":`DD-MM-RRRR`,"prefs.date.mdy":`MM-DD-RRRR`,"prefs.time.locale":`Zgodnie z językiem`,"prefs.time.h24":`24-godzinny`,"prefs.time.h12":`12-godzinny`,"prefs.tz.device":`Zgodnie z tym urządzeniem ({zone})`,"prefs.on":`Włączone`,"prefs.off":`Wyłączone`,"prefs.serverFormat":`Serwer nigdy nie wysyła sformatowanego napisu. Wysyła wartość; interfejs ją odczytuje.`,"dashboard.noProjects":`Nie należysz jeszcze do żadnego projektu`,"project.tab.overview":`Przegląd`,"project.tab.members":`Członkowie`,"project.tab.skills":`Skille`,"project.tab.activity":`Aktywność`,"project.notBuilt.title":`Jeszcze nie zrobione`,"project.notBuilt.artifacts":`Artefakty, notatki, polityki i sekrety mają zaprojektowane ekrany, ale na razie nie mają ścieżki odczytu w API.`,"context.title":`Kontekst`,"context.lead":`Dokładnie to, co agent dostaje, gdy tu startuje — ten sam złożony widok, który zwraca MCP, wyrysowany dla człowieka. Jeśli agent zachowuje się dziwnie, to pierwsze miejsce do sprawdzenia.`,"context.role":`Działa jako`,"context.capabilities":`Może`,"context.assembled":`Złożono`,"context.budget":`Budżet`,"context.budgetUsed":`{used} z {limit}`,"context.budgetLead":`Paczka ma limit rozmiaru, a to, co się nie mieści, zostaje nazwane, a nie ucięte. Agent, który nie odróżni „nic więcej nie ma” od „było więcej i tego nie dostałeś”, będzie pewnie działał na połowie obrazu.`,"context.truncated":`Pominięto`,"context.nothingTruncated":`Nic nie zostało pominięte`,"context.nothingTruncatedBody":`Wszystko, co ten projekt zawiera, zmieściło się w budżecie.`,"context.column.what":`Co`,"context.column.ref":`Które`,"context.column.why":`Dlaczego`,"context.included":`Zawarte`,"context.artifacts":`{count, plural, one {# artefakt} few {# artefakty} many {# artefaktów} other {# artefaktu}}`,"context.skills":`{count, plural, one {# skill} few {# skille} many {# skilli} other {# skilla}}`,"context.recentEvents":`Ostatnie zdarzenia`,"context.noHandoff":`W paczce nie ma przekazania`,"context.noHandoffBody":`Agentowi, który tu startuje, mówi się, że nie ma czego kontynuować.`,"context.budgetLimit":`Limit rozmiaru`,"context.apply":`Złóż ponownie`,"artifacts.title":`Artefakty`,"artifacts.lead":`Wspólny magazyn, z którego agenci czytają i do którego piszą. Każdy zapis tworzy nową wersję; nic nie jest nadpisywane w miejscu, więc zły zapis można przeczytać z pominięciem, a nie odzyskiwać z kopii zapasowej.`,"artifacts.column.path":`Ścieżka`,"artifacts.column.version":`Wersja`,"artifacts.column.size":`Rozmiar`,"artifacts.column.hash":`Skrót treści`,"artifacts.empty":`Na razie żadnych artefaktów`,"artifacts.emptyBody":`Pierwszy powstaje, gdy agent zapisze coś przez API, CLI albo MCP.`,"artifacts.history":`Wersje`,"artifacts.content":`Treść`,"artifacts.select":`Wybierz artefakt`,"artifacts.selectBody":`Wybierz ścieżkę po lewej, aby zobaczyć jej wersje i treść.`,"artifacts.binary":`To nie jest tekst`,"artifacts.binaryBody":`Typ treści mówi, że to nie tekst, więc nie jest wyświetlany. Wersja, rozmiar i skrót powyżej to to, co ten ekran może o tym powiedzieć.`,"artifacts.viewing":`Wyświetlana wersja {version}`,"artifacts.latest":`Najnowsza`,"artifacts.edit":`Edytuj`,"artifacts.new":`Nowy artefakt`,"artifacts.save":`Zapisz`,"artifacts.delete":`Usuń`,"artifacts.confirmDelete":`Usunąć {path}? Jego wersje odejdą razem z nim, a wszystko, co czyta tę ścieżkę, zacznie padać.`,"artifacts.editingFrom":`Edycja od wersji {version}`,"artifacts.editingNew":`Nowy artefakt na tej ścieżce`,"artifacts.newPath":`Ścieżka`,"artifacts.newPathHelp":`notatki/decyzje.md`,"artifacts.contentType":`Typ treści`,"artifacts.staleWrite":`Ktoś zapisał nowszą wersję, gdy Ty edytowałaś lub edytowałeś`,"artifacts.staleWriteBody":`Twój zapis został odrzucony, a nie zastosowany — zastosowanie go usunęłoby pracę tej osoby. Wczytaj najnowszą wersję, przenieś do niej swoją zmianę i zapisz ponownie.`,"artifacts.reload":`Wczytaj najnowszą wersję`,"artifacts.concurrency":`Zapis nazywa wersję, od której wyszedł. Jeśli ktoś inny zapisał w tym czasie, serwer odrzuca zapis, zamiast go nadpisać.`,"artifacts.binaryNoEdit":`To nie tekst, więc nie da się tego tutaj edytować. Agenci zapisują to przez API, CLI i MCP.`,"secrets.title":`Sekrety`,"secrets.lead":`Tylko nazwy i odniesienia. Wartość wchodzi raz i nigdy nie wychodzi przez ten interfejs — projekt dostaje odniesienie, które wręcza gate’owi.`,"secrets.column.name":`Nazwa`,"secrets.add":`Dodaj sekret`,"secrets.value":`Wartość`,"secrets.delete":`Usuń`,"secrets.empty":`W tym projekcie nie ma sekretów`,"secrets.emptyBody":`Dodaj jakiś tutaj albo przez CLI.`,"secrets.neverShown":`Wartość zapisuje się raz i potem nikt nie może jej już odczytać, żadnym adapterem. Usunięcie i dodanie od nowa to jedyny sposób, by ją zmienić.`,"secrets.confirmDelete":`Usunąć sekret {name}? Wszystko, co używa jego odniesienia, zacznie padać.`,"gates.title":`Polityki`,"gates.lead":`Gate’y powiązane z tym projektem i te, które dziedziczy. Gate uruchamia się na hooku i może odmówić operacji — odmowa trafia na osi czasu aktywności.`,"gates.column.gate":`Gate`,"gates.column.hook":`Hook`,"gates.column.scope":`Powiązany na poziomie`,"gates.column.enabled":`Stan`,"gates.enabled":`Wymuszany`,"gates.disabled":`Wyłączony`,"gates.empty":`Żaden gate tu nie obowiązuje`,"gates.emptyBody":`Nic nie przechwytuje operacji w tym projekcie.`,"gates.bind":`Powiąż gate`,"gates.bindLead":`Powiązać można tylko gate’y, które serwer faktycznie zarejestrował; powiązanie wskazujące niezarejestrowany gate wywala całą operację, zamiast zostać zignorowane, więc ta lista jest tym, co istnieje.`,"gates.gateName":`Gate`,"gates.hook":`Hook`,"gates.unbind":`Rozwiąż`,"gates.confirmUnbind":`Rozwiązać {gate} z {hook}? Operacje, którym odmawiał, zaczną przechodzić.`,"gates.inherited":`Odziedziczony`,"skills.override":`Nadpisz`,"skills.overrideLead":`Powiąż inną wersję na poziomie tego projektu, zasłaniając to, co narzucił szerszy poziom. Powiązanie oznaczone jako nienadpisywalne tego odmawia — po to właśnie jest ta flaga.`,"skills.overrideVersion":`Wersja do powiązania`,"orgs.create":`Nowa organizacja`,"orgs.createLead":`Zostajesz jej pierwszą osobą właścicielską. Projekty i skille będzie można potem do niej przypisać.`,"orgs.name":`Nazwa`,"orgs.addMember":`Dodaj członka`,"orgs.addMemberLead":`Rola w organizacji mówi o człowieku, więc to pole nazywa konto, a nie principala — agent działa wewnątrz projektu i takiej roli mieć nie może.`,"orgs.userId":`Identyfikator konta`,"settings.title":`Ustawienia projektu`,"settings.lead":`Czym jest ten projekt i co da się w nim zmienić z tego miejsca.`,"settings.identity":`Tożsamość`,"settings.visibility":`Widoczność`,"settings.encryption":`Szyfrowanie`,"settings.encryptionBody":`Treść jest szyfrowana w spoczynku kluczem należącym do tego projektu, który sam jest owinięty kluczem głównym instalacji. Treści przekazań i sekrety przechodzą przez tę kopertę; bajty artefaktów idą do magazynu obiektów.`,"settings.danger":`Nieodwracalne`,"settings.noWrites":`Nic na tym ekranie nie da się tu zmienić: API nie ma dla projektu ani aktualizacji, ani usunięcia. Zmiana nazwy, zmiana widoczności i usunięcie to operacje wiersza poleceń, a przycisk, który otwiera okno i potem pada, byłby gorszy niż jego brak.`,"settings.connect":`Podłączanie agenta`,"settings.connectLead":`Skieruj klienta MCP na ten serwer z osobistym tokenem dostępu. Projekt nazywa się przy każdym wywołaniu, więc jeden token dosięga wszystkich projektów, do których należysz.`,"settings.mcpEndpoint":`Punkt końcowy MCP`,"settings.restEndpoint":`REST`,"dashboard.waitingLead":`Projekty, w których przekazanie jest otwarte albo przejęte — praca zostawiona przez kogoś dla następnego.`,"history.title":`Rozmowy`,"history.lead":`To, co klienci zapisali z własnych sesji, aby przekazanie mogło wskazać miejsce, w którym praca naprawdę się odbyła. Nic tutaj nie jest zapisywane przez ten interfejs — wnoszą to sami klienci.`,"history.column.conversation":`Rozmowa`,"history.column.started":`Rozpoczęto`,"history.column.by":`Rozpoczął`,"history.column.type":`Typ`,"history.column.recorded":`Zapisano`,"history.objects":`Zapisane obiekty`,"history.lineage":`Pochodzenie`,"history.lineageLead":`Jak jeden obiekt powstał z drugiego — podsumowanie z transkryptu, kompakcja z podsumowania. To właśnie chroni obiekt pochodny od pomylenia z oryginałem.`,"history.column.from":`Pochodzi z`,"history.column.to":`Dało`,"history.column.kind":`Relacja`,"history.select":`Wybierz rozmowę`,"history.selectBody":`Wybierz jedną po lewej, aby zobaczyć, co w niej zapisano.`,"history.empty":`Nie zapisano żadnych rozmów`,"history.emptyBody":`Klient zapisuje je w trakcie pracy. Do tego projektu nic jeszcze nie wniosło historii.`,"history.noObjects":`W tej rozmowie nic nie zapisano`,"history.noLineage":`Brak pochodnych`,"history.noLineageBody":`Każdy obiekt tutaj zapisano bezpośrednio, żaden nie powstał z innego.`,"history.notText":`To nie tekst`,"history.notTextBody":`Obiekt historii to to, co zapisał klient, a te bajty nie są poprawnym UTF-8. Skrót i typ powyżej to to, co ten ekran może o tym powiedzieć.`,"events.title":`Zdarzenia`,"events.lead":`Strumień skrzynki nadawczej. Zdarzenie jest tym, co konsumują inne systemy; wpis audytu obok jest tym, co czyta człowiek.`,"events.column.seq":`Nr`,"events.column.type":`Typ`,"events.column.resource":`Zasób`,"events.column.payload":`Ładunek`,"events.empty":`Na razie żadnych zdarzeń`,"handoff.createLead":`To, czego następny agent potrzebuje, by kontynuować. Tutaj pisze to człowiek; agenci piszą to samo przez MCP.`,"handoff.summaryHelp":`Jedna linia. O co w tej pracy chodzi.`,"handoff.completedHelp":`Co jest już zrobione, żeby nikt nie zrobił tego dwa razy.`,"handoff.nextHelp":`Co robić dalej, konkretnie na tyle, by dało się zacząć.`,"handoff.confirmClose":`Zamknąć to przekazanie? Przestanie być bieżącym i nikt nie będzie mógł go przejąć.`,"projects.create":`Nowy projekt`,"projects.createLead":`Ścieżka i nazwa. Ścieżka to sposób, w jaki ludzie się do niego odwołują, i potem nie da się jej zmienić; zostajesz osobą właścicielską.`,"projects.path":`Ścieżka`,"projects.pathHelp":`przestrzeń-nazw/identyfikator`,"projects.name":`Nazwa wyświetlana`,"projects.created":`Utworzono {path}`,"handoff.history":`Wcześniejsze przekazania`,"handoff.column.created":`Utworzono`,"handoff.column.status":`Stan`,"skill.versions":`Wersje`,"skill.versionsLead":`Wszystkie wersje kiedykolwiek opublikowane pod tą nazwą. Opublikowana wersja jest niezmienna — kolejna publikacja dodaje tu wiersz, nigdy żadnego nie zmienia.`,"skill.content":`Treść`,"skill.contentLead":`To, co agent dostaje, gdy ta wersja zostanie rozstrzygnięta.`,"skill.provenance":`Pochodzenie`,"skill.checksum":`Suma kontrolna`,"skill.capabilities":`Zadeklarowane uprawnienia`,"skill.author":`Autor`,"skill.origin":`Źródło`,"skill.promote":`Podnieś`,"skill.promoteLead":`Przenieś skill na szerszą półkę, żeby widziało go więcej projektów. Tylko w jedną stronę: zawężenie z powrotem wyciągnęłoby go spod powiązań, które w chwili powstania były zasadne.`,"skill.livesAtNow":`Mieszka w`,"skill.alreadyWidest":`Już na półce instalacji`,"skill.alreadyWidestBody":`To najszerszy poziom, jaki istnieje, więc nie ma go gdzie przenieść dalej.`,"skill.newVersion":`Opublikuj nową wersję`,"skill.newVersionLead":`Opublikowana wersja jest niezmienna, więc poprawienie skilla znaczy opublikowanie następnej. Obie zostają, a to, co jest przypięte do starej, dalej dostaje starą, dopóki się tego nie przestawi.`,"skill.newVersionFrom":`Wychodząc z v{version}`,"skill.publishedVersion":`Opublikowano v{version}`,"skill.promoteTo":`Przenieś do`,"skill.promoted":`Mieszka teraz na poziomie {scope}`,"skill.install":`Zainstaluj`,"skill.installed":`Zainstalowany`,"skill.installLead":`Przypnij wersję skilla do tego projektu. Powiązanie nazywa jedną konkretną wersję — nie ma rozstrzygania zakresów wersji, więc nic się pod Tobą nie zmienia.`,"skill.notFound":`Nie ma takiego skilla`,"skill.notFoundBody":`Mógł zostać opublikowany w miejscu, którego nie widzisz.`,"skill.backToRegistry":`Wróć do rejestru`,"skill.pinLead":`Przypięte powiązanie to takie, o którym ten projekt zdecydował i którego nie chce ruszać. Przypiąć można tylko powiązanie zrobione tutaj — odziedziczone nie należy do tego projektu.`,"skill.inherited":`Odziedziczone`,"skill.pin":`Przypnij`,"skill.unpin":`Odepnij`,"skill.pinned":`Przypięte`,"registry.livesAt":`Mieszka w`,"registry.empty":`Katalog jest pusty`,"registry.emptyBody":`Opublikuj skill z projektu albo podnieś któryś na półkę instalacji.`,"activity.empty":`Jeszcze nic się tu nie stało`,"activity.emptyBody":`Odczyty i zapisy przez API, CLI i MCP trafiają wszystkie na tę osi czasu.`,"error.quota.title":`Nie ma na to miejsca`,"error.quota.body":`Osiągnięto limit przestrzeni dla tego użytkownika lub organizacji. Usuń niepotrzebne artefakty albo poproś administratora instalacji o większy limit.`,"admin.tab.storage":`Przestrzeń`,"admin.storage.title":`Przestrzeń`,"admin.storage.lead":`Ile zajmuje każdy użytkownik i każda organizacja oraz ile może zająć. Zapisy przekraczające limit są odrzucane; usuwanie działa zawsze.`,"admin.storage.namespaces":`Użytkownicy i organizacje`,"admin.storage.none":`Nie ma jeszcze użytkowników ani organizacji`,"admin.storage.help":`Wersje artefaktów, historia rozmów i pakiety skilli, liczone przez bazę danych. To nie jest zajętość dysku: usunięty artefakt przestaje się liczyć, zanim operator go trwale usunie.`,"admin.storage.owner":`Właściciel`,"admin.storage.used":`Zajęte`,"admin.storage.limit":`Limit`,"admin.storage.personal":`Osobista`,"admin.storage.organization":`Organizacja`,"admin.storage.default":`{limit} (domyślny)`,"admin.storage.custom":`{limit} (ustawiony tutaj)`,"admin.storage.unlimited":`Bez limitu`,"admin.storage.noDefault":`Bez limitu (brak wartości domyślnej)`,"admin.storage.change":`Zmień limit`,"admin.storage.limitFor":`Limit przestrzeni dla {name}`,"admin.storage.useDefault":`Domyślny serwera`,"admin.storage.useCustom":`Własny limit`,"admin.storage.useUnlimited":`Bez limitu`,"admin.storage.amount":`Ilość`,"admin.storage.unit":`Jednostka`,"admin.storage.save":`Zapisz limit`,"prefs.storage.title":`Przestrzeń`,"prefs.storage.help":`Wersje artefaktów, historia rozmów i pakiety skilli. Usunięcie artefaktu zwalnia jego miejsce.`,"prefs.storage.none":`Nic jeszcze nie zapisano`,"prefs.storage.ofLimit":`{used} z {limit}`,"prefs.storage.unlimited":`{used} · bez limitu`,"project.tab.plans":`Plany`,"dashboard.workingNow":`Kto nad czym pracuje`,"plans.title":`Plany`,"plans.lead":`Fazy, plany w nich i kto jest teraz na którym kroku — zarówno agenci, jak i ludzie.`,"plans.stale":`Ostatnie odświeżenie się nie powiodło. Widok może być nieaktualny; ponowi się samo.`,"plans.workingNow":`Teraz w pracy`,"plans.refreshes":`Odświeża się co 10 sekund`,"plans.blockedTitle":`{count, plural, one {# zablokowany krok} few {# zablokowane kroki} many {# zablokowanych kroków} other {# zablokowanego kroku}}`,"plans.nobody":`nikt`,"plans.nobodyPresent":`Nikt tu teraz nie pracuje`,"plans.nobodyPresentBody":`Agenci pojawiają się tu, gdy wywołują plan.report; ludzie — gdy wezmą krok przyciskiem „Pracuję nad tym”.`,"plans.column.who":`Kto`,"plans.column.where":`Gdzie`,"plans.column.seen":`Widziany`,"plans.onItem":`{plan} → {item}`,"plans.inProject":`W projekcie, bez konkretnego kroku`,"plans.you":`ty`,"plans.agent":`agent`,"plans.idleSince":`Bezczynny od {when}`,"plans.activeFor":`Aktywny od {duration}`,"plans.tracked":`{duration} zarejestrowane`,"plans.tokensReported":`{count, plural, one {# token zgłoszony} few {# tokeny zgłoszone} many {# tokenów zgłoszonych} other {# tokenu zgłoszonego}}`,"plans.phase.planned":`Zaplanowana`,"plans.phase.active":`Aktywna`,"plans.phase.done":`Zakończona`,"plans.phases":`Fazy`,"plans.noPhases":`Nie ma jeszcze faz`,"plans.noPhasesBody":`Faza to odcinek pracy — „Migracja”, „Wydanie 1.2”. Plany mogą być poza fazami.`,"plans.column.phase":`Faza`,"plans.column.progress":`Postęp`,"plans.column.effort":`Nakład`,"plans.column.status":`Status`,"plans.doneOf":`{done} z {total} zrobione`,"plans.phaseStatusFor":`Status: {name}`,"plans.newPhase":`Nowa faza`,"plans.newPhasePlaceholder":`np. Wydanie 1.2`,"plans.addPhase":`Dodaj fazę`,"plans.planStatus.draft":`Szkic`,"plans.planStatus.active":`Aktywny`,"plans.planStatus.done":`Zakończony`,"plans.planStatus.abandoned":`Porzucony`,"plans.plans":`Plany`,"plans.noPlans":`Nie ma jeszcze planów`,"plans.noPlansBody":`Agent zapisuje swój plan przez plan.create; możesz też napisać go poniżej.`,"plans.column.plan":`Plan`,"plans.blockedCount":`{count, plural, one {# zablokowany} few {# zablokowane} many {# zablokowanych} other {# zablokowanego}}`,"plans.openPlan":`Otwórz`,"plans.item.open":`Otwarty`,"plans.item.in_progress":`W toku`,"plans.item.done":`Zrobiony`,"plans.item.blocked":`Zablokowany`,"plans.item.skipped":`Pominięty`,"plans.planStatusFor":`Status: {name}`,"plans.phaseFor":`Faza: {name}`,"plans.noPhase":`Bez fazy`,"plans.confirmDelete":`Usunąć plan „{name}” ze wszystkimi krokami? Tego nie można cofnąć.`,"plans.deletePlan":`Usuń plan`,"plans.noItems":`Ten plan nie ma jeszcze kroków`,"plans.column.step":`Krok`,"plans.check":`Kontrola`,"plans.task":`Zadanie`,"plans.statusFor":`Status: {item}`,"plans.workOnThis":`Pracuję nad tym`,"plans.workOnThisHelp":`Oznacz ten krok jako w toku i pokaż się przy nim w „Teraz w pracy”`,"plans.addItems":`Dodaj kroki — jeden na linię`,"plans.kind":`Dodaj jako`,"plans.addItemsButton":`{count, plural, one {Dodaj # krok} few {Dodaj # kroki} many {Dodaj # kroków} other {Dodaj # kroku}}`,"plans.newPlanTitle":`Tytuł nowego planu`,"plans.newPlanItems":`Kroki — jeden na linię`,"plans.createPlan":`Utwórz plan`,"plans.search":`Szukaj w planach`,"plans.searchPlaceholder":`Słowa z planu, kroku lub notatki`,"plans.searchButton":`Szukaj`,"plans.noHits":`Nic nie pasuje do „{query}”`,"plans.newPlan":`Nowy plan`,"plans.addSteps":`Dodaj kroki`,"plans.tokensBreakdown":`{in} na wejściu · {out} na wyjściu · {cacheRead} odczytane z cache · {cacheWrite} zapisane do cache`};export{e as pl};